#include <Raven.h>

static void on_click(Rid sender, const char* action, void* user_data) {
	Rlabel_set_text(Rwidget_find(g_window, "status"), "Clicked!");
}

int main(void) {
	if (!Rinit()) return 1;
	Raction_bind("counter.click", on_click, NULL);
	Rid window = Rwindow_create_from_xml_file("main.xml");
	while (Rwait_frame(-1.0)) {
	}
	Rshutdown();
	return 0;
}
